const synthetics = require("Synthetics");
const log = require("SyntheticsLogger");

const TARGET_URL = "https://martian-imperial-year-table.c4se.jp/transform";

// グレゴリオ曆側の入力欄 (年, 月, 日, 時, 分, 秒, タイムゾーン) に順番に入力する値。
const GREGORIAN_INPUT_VALUES = ["2026", "01", "01", "00", "00", "00", "+09:00"];

const EXPECTED_MARTIAN_ISO = "1428-17-28T07:04:27+00:00";

const transformCheckBlueprint = async function () {
  const page = await synthetics.getPage();

  await synthetics.executeStep("navigateToTransform", async function () {
    const response = await page.goto(TARGET_URL, {
      waitUntil: "domcontentloaded",
      timeout: 30000,
    });

    if (!response) {
      throw new Error("ページの讀み込みに失敗しました。");
    }
    if (response.status() !== 200) {
      throw new Error(`ページの讀み込みに失敗しました。status=${response.status()}`);
    }
  });

  await synthetics.executeStep("inputGregorianDate", async function () {
    // 變換フォームは1つ目がグレゴリオ曆、2つ目が帝國火星曆。
    const forms = await page.$$("form.transform-form");
    if (forms.length < 2) {
      throw new Error(`變換フォームが見つかりませんでした。forms.length=${forms.length}`);
    }

    const gregorianInputs = await forms[0].$$("input");
    if (gregorianInputs.length < GREGORIAN_INPUT_VALUES.length) {
      throw new Error(`グレゴリオ曆の入力欄が不足しています。inputs.length=${gregorianInputs.length}`);
    }

    // React の制禦下にある number/text input は value の直接書き換へでは
    // onChange が發火しないため、實際のクリック + キー入力で狀態を更新する。
    for (let i = 0; i < GREGORIAN_INPUT_VALUES.length; i++) {
      const input = gregorianInputs[i];
      await input.click({ clickCount: 3 });
      await input.type(GREGORIAN_INPUT_VALUES[i], { delay: 20 });
    }

    await page.keyboard.press("Tab");
  });

  await synthetics.executeStep("verifyMartianDate", async function () {
    await page.waitForFunction(
      (expected) => {
        const forms = document.querySelectorAll("form.transform-form");
        if (forms.length < 2) return false;
        const box = forms[1].closest(".box");
        const code = box ? box.querySelector("code") : null;
        return !!code && code.textContent.trim() === expected;
      },
      { timeout: 15000 },
      EXPECTED_MARTIAN_ISO,
    );

    const resultText = await page.evaluate(() => {
      const forms = document.querySelectorAll("form.transform-form");
      const box = forms[1].closest(".box");
      const code = box ? box.querySelector("code") : null;
      return code ? code.textContent.trim() : null;
    });

    log.info(`帝國火星曆の變換結果: ${resultText}`);

    await synthetics.takeScreenshot("result", "loaded");

    if (resultText !== EXPECTED_MARTIAN_ISO) {
      throw new Error(`變換結果が期待値と異なります。expected="${EXPECTED_MARTIAN_ISO}" actual="${resultText}"`);
    }
  });
};

exports.handler = async () => {
  return await transformCheckBlueprint();
};
